def control(obs):
    t=obs['t']
    h=obs['hitch_deg']
    if obs['motion']['hold_s']>0.05:
        return (0.0,0.0,170)
    if st['ph']==0:
        if st['t0'] is None: st['t0']=t
        if t-st['t0']>2.5 and abs(h)<6:
            st['ph']=1
        else:
            return (0.0,1.0,170)
    s=max(-20.0,min(25.0,2.0*(h+6.0)))
    return (s,-0.5,170)

